<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{getVersion}from'@/api/versions';import StatusTag from'@/components/StatusTag.vue';const route=useRoute();const item=ref<any>();onMounted(async()=>item.value=await getVersion(Number(route.params.id)))</script>
<template><div class="page" v-if="item"><div class="page-title">{{item.version_no}} {{item.name}}</div><el-card><StatusTag :status="item.status"/><el-descriptions :column="1" border style="margin-top:14px"><el-descriptions-item label="计划上线">{{item.planned_release_date||'-'}}</el-descriptions-item><el-descriptions-item label="实际上线">{{item.released_at||'-'}}</el-descriptions-item><el-descriptions-item label="说明">{{item.description||'-'}}</el-descriptions-item></el-descriptions></el-card></div></template>
